<?php require_once "../db.php"; require_role("Student");$uid=current_id();$st=$conn->prepare("SELECT COUNT(*) attempts,COALESCE(SUM(score),0) score,COALESCE(SUM(total_questions),0) total,COALESCE(SUM(correct_answers),0) correct,COALESCE(SUM(wrong_answers),0) wrong FROM quiz_history WHERE student_id=?");$st->bind_param("i",$uid);$st->execute();$d=$st->get_result()->fetch_assoc();$p=$d["total"]?round($d["score"]/$d["total"]*100,1):0;?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Performance</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container-fluid"><div class="row"><div class="col-lg-2 p-0"><?php include "../partials/student_sidebar.php";?></div><main class="col-lg-10"><div class="py-4"><h2 class="fw-bold">Performance</h2><p class="text-muted">Track your quiz performance.</p><div class="row g-3"><?php foreach([["Attempts",$d["attempts"]],["Correct",$d["correct"]],["Wrong",$d["wrong"]],["Average",$p."%"]] as $x):?><div class="col-md-6 col-xl-3"><div class="card stat-card p-4"><small class="text-muted"><?=$x[0]?></small><h2 class="fw-bold"><?=$x[1]?></h2></div></div><?php endforeach;?></div><div class="card panel-card mt-4"><div class="card-body"><h5 class="fw-bold">Overall Progress</h5><div class="progress" style="height:28px"><div class="progress-bar" style="width:<?=$p?>%"><?=$p?>%</div></div></div></div></div></main></div></div></body></html>
